create or replace function public.export_company_backup() returns jsonb language plpgsql security invoker set search_path=''as $$declare c uuid;begin select company_id into c from public.profiles where id=(select auth.uid())and is_active and role=any(array['proprietario','administrador']);if c is null then raise exception'Acesso restrito';end if;return jsonb_build_object('format','petshop-backup','version',1,'exported_at',now(),'company_id',c,'customers',coalesce((select jsonb_agg(to_jsonb(x))from public.customers x where company_id=c),'[]'),'pets',coalesce((select jsonb_agg(to_jsonb(x))from public.pets x where company_id=c),'[]'),'services',coalesce((select jsonb_agg(to_jsonb(x))from public.services x where company_id=c),'[]'),'suppliers',coalesce((select jsonb_agg(to_jsonb(x))from public.suppliers x where company_id=c),'[]'),'products',coalesce((select jsonb_agg(to_jsonb(x))from public.products x where company_id=c),'[]'),'appointments',coalesce((select jsonb_agg(to_jsonb(x))from public.appointments x where company_id=c),'[]'),'sales',coalesce((select jsonb_agg(to_jsonb(x))from public.sales x where company_id=c),'[]'),'service_orders',coalesce((select jsonb_agg(to_jsonb(x))from public.service_orders x where company_id=c),'[]'),'financial_transactions',coalesce((select jsonb_agg(to_jsonb(x))from public.financial_transactions x where company_id=c),'[]'),'stock_movements',coalesce((select jsonb_agg(to_jsonb(x))from public.stock_movements x where company_id=c),'[]'));end$$;
create or replace function public.import_company_catalog(p_data jsonb)returns jsonb language plpgsql security invoker set search_path=''as $$declare c uuid;cc int:=0;sc int:=0;pc int:=0;begin select company_id into c from public.profiles where id=(select auth.uid())and is_active and role=any(array['proprietario','administrador']);if c is null then raise exception'Acesso restrito';end if;if p_data->>'format'<>'petshop-backup'or(p_data->>'version')::int<>1 then raise exception'Arquivo inválido';end if;insert into public.customers(company_id,name,cpf,phone,whatsapp,email)select c,trim(x.name),nullif(x.cpf,''),x.phone,x.whatsapp,x.email from jsonb_to_recordset(coalesce(p_data->'customers','[]'))x(name text,cpf text,phone text,whatsapp text,email text)where length(trim(x.name))>=2 and not exists(select 1 from public.customers q where q.company_id=c and((x.cpf<>''and q.cpf=x.cpf)or(x.email is not null and lower(q.email)=lower(x.email))));get diagnostics cc=row_count;insert into public.services(company_id,name,description,category,estimated_duration_minutes,base_price,is_active)select c,trim(x.name),x.description,coalesce(x.category,'Banho e Tosa'),coalesce(x.estimated_duration_minutes,45),coalesce(x.base_price,0),coalesce(x.is_active,true)from jsonb_to_recordset(coalesce(p_data->'services','[]'))x(name text,description text,category text,estimated_duration_minutes int,base_price numeric,is_active boolean)where length(trim(x.name))>=2 on conflict(company_id,name)do update set description=excluded.description,base_price=excluded.base_price,is_active=excluded.is_active;get diagnostics sc=row_count;insert into public.products(company_id,name,description,category,barcode,unit,cost_price,sale_price,current_stock,min_stock,max_stock,is_active)select c,trim(x.name),x.description,coalesce(x.category,'Alimentação'),nullif(x.barcode,''),coalesce(x.unit,'UN'),coalesce(x.cost_price,0),coalesce(x.sale_price,0),coalesce(x.current_stock,0),coalesce(x.min_stock,0),coalesce(x.max_stock,0),coalesce(x.is_active,true)from jsonb_to_recordset(coalesce(p_data->'products','[]'))x(name text,description text,category text,barcode text,unit text,cost_price numeric,sale_price numeric,current_stock numeric,min_stock numeric,max_stock numeric,is_active boolean)where length(trim(x.name))>=2 and not exists(select 1 from public.products p where p.company_id=c and((x.barcode<>''and p.barcode=x.barcode)or lower(p.name)=lower(x.name)));get diagnostics pc=row_count;return jsonb_build_object('customers',cc,'services',sc,'products',pc);end$$;
revoke all on function public.export_company_backup(),public.import_company_catalog(jsonb)from public,anon;grant execute on function public.export_company_backup(),public.import_company_catalog(jsonb)to authenticated;
